examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
    HStack(spacing: MonarchTokens.Space.space2) {
        MonarchButton({{receive}}, variant: .secondary, size: .sm) {
            messages.append(Self.message(messages.count + {{history.from}}))
        }
        MonarchButton({{goTo.label}}, variant: .ghost, size: .sm) { scrollTo = {{goTo.id}} }
    }
    MonarchVirtualMessageList(
        messages,
        firstUnreadID: {{firstUnreadId}},
        scrollToID: scrollTo,
        hasOlder: true,
        now: Self.now,
        onLoadOlder: {},
        row: { message, context in
            MonarchMessageRow(
                MonarchMessageRowAuthor(message.authorID ?? ""),
                time: message.time,
                now: Self.now,
                isGrouped: context.isGrouped
            ) {
                Text(message.text)
            }
        }
    )
    .frame(height: 720)
}
.environment(\.locale, Locale(identifier: {{locale}}))

examples.setupTemplate:
struct ChatMessage: MonarchVirtualMessageListItem {
    let id: String
    let time: Date
    let authorID: String?
    let text: String
}
private static let now = Date(timeIntervalSinceReferenceDate: 800_000_000)
private static let people = [{{people.0}}, {{people.1}}, {{people.2}}]
private static let lines = [{{lines.0}}, {{lines.1}}, {{lines.2}}, {{lines.3}}, {{lines.4}}, {{lines.5}}]
private static func message(_ n: Int) -> ChatMessage {
    ChatMessage(
        id: "msg-\(n)",
        time: now.addingTimeInterval(TimeInterval(n - ({{history.from}} + {{history.count}})) * 420),
        authorID: people[(n / 3) % people.count],
        text: "\(lines[n % lines.count]) (#\(n + 1))"
    )
}
@State private var messages = ({{history.from}}..<({{history.from}} + {{history.count}})).map { Self.message($0) }
@State private var scrollTo: String?

