examples.setup:
struct ChatMessage: MonarchVirtualMessageListItem {
    let id: Int
    let time: Date
    let authorID: String?
    let text: String
}
private let now = Date(timeIntervalSinceReferenceDate: 800_000_000)
@State private var messages: [ChatMessage] = (0..<12).map { (index: Int) -> ChatMessage in
    ChatMessage(
        id: index,
        time: Date(timeIntervalSinceReferenceDate: 800_000_000).addingTimeInterval(TimeInterval((index - 12) * 120)),
        authorID: index % 3 == 0 ? "ben" : "ana",
        text: "Message \(index)"
    )
}
